-- Enrich existing catalog content without regrading or changing historical snapshots.
ALTER TABLE interviews ADD COLUMN contract TEXT NOT NULL DEFAULT '{}';
WITH enrichment(slug, content) AS (VALUES
('register-field-update','{"estimatedMinutes": 15, "focusAreas": ["volatile", "bitwise", "registers"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 15, "objectives": ["Modify a masked field in a volatile register while preserving unrelated bits"], "hints": {"nudge": "Which bits belong to the field, and which must survive the update?", "approach": "Describe the register as two disjoint regions: preserved bits and replacement bits. Check that the replacement cannot set bits outside its field mask."}}'),
('mmio-status-snapshot','{"estimatedMinutes": 25, "focusAreas": ["volatile", "mmio", "bitwise", "registers"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "reasoning"}, "targetMinutes": 25, "objectives": ["Decode a volatile status register and acknowledge write-one-to-clear flags"], "hints": {"nudge": "Does reading a hardware register twice necessarily give the same value?", "approach": "Use one status snapshot for decoding. Treat write-one-to-clear acknowledgements separately from ordinary read-modify-write updates; acknowledge only the requested flags."}}'),
('freertos-ready-scheduler','{"estimatedMinutes": 40, "focusAreas": ["rtos", "scheduling", "bitwise", "state-machines"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 40, "objectives": ["Implement a tiny priority scheduler with ready bits and tick-based delays"], "hints": {"nudge": "Separate task readiness from the rule that chooses the next task.", "approach": "Track delay expiration and ready-state changes first, then select the highest-priority eligible task. Trace a tick with several tasks becoming ready together."}}'),
('bf-strlen','{"estimatedMinutes": 12, "focusAreas": ["pointers", "memory", "c-standard-library"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 12, "objectives": ["Implement a null-terminated string length routine without using libc"], "hints": {"nudge": "What byte marks the end of the string?", "approach": "Track how many bytes precede the first terminator. Check the empty-string case before reasoning about longer strings."}}'),
('can-control-frame','{"estimatedMinutes": 30, "focusAreas": ["communication-protocols", "endianness", "bitwise"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Decode mixed-endian fields from an 8-byte CAN control frame"], "hints": {"nudge": "The two multi-byte fields do not use the same byte order.", "approach": "Separate validation, checksum, and decoding. Label each byte with its significance for its own field, and reason about the signed torque word after reconstructing its bits."}}'),
('debug-frame-length','{"estimatedMinutes": 25, "focusAreas": ["debugging", "endianness", "memory-safety"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "reasoning"}, "targetMinutes": 25, "objectives": ["Fix a C frame parser with endian and bounds-checking bugs"], "hints": {"nudge": "Which checks must happen before a byte can be read?", "approach": "Trace the shortest valid frame and the first truncated frame. Reconstruct the declared length using the stated byte order, then compare it with the available payload without allowing arithmetic wraparound."}}'),
('pack-actuator-command','{"estimatedMinutes": 30, "focusAreas": ["bitfields", "packing", "signed-values"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Pack and unpack a compact 32-bit actuator command"], "hints": {"nudge": "Write down the bit range and signedness of each field.", "approach": "Treat packing and unpacking as inverse operations. Isolate each field before shifting it into place, and distinguish sign reconstruction from ordinary unsigned extraction."}}'),
('debounce-button-isr','{"estimatedMinutes": 25, "focusAreas": ["interrupts", "state-machines", "bit-operations"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 25, "objectives": ["Implement an 8-sample shift-register debouncer with rising/falling edge events"], "hints": {"nudge": "A single sample should not immediately change the debounced state.", "approach": "Keep sample history separate from the accepted button state. Decide when a history window is stable, then emit an event only when the accepted state changes."}}'),
('spi-sensor-frame','{"estimatedMinutes": 30, "focusAreas": ["communication-protocols", "endianness", "bitwise"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Validate and parse a fixed-length SPI sensor response with sync and checksum bytes"], "hints": {"nudge": "What must be true before the frame can be interpreted as sensor data?", "approach": "Validate the frame shape, synchronization bytes, and checksum before decoding fields. Follow the specified byte order and signedness for each value."}}'),
('status-word-decode','{"estimatedMinutes": 20, "focusAreas": ["masks", "shifts", "flags"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 20, "objectives": ["Extract health flags and small fields from a telemetry status word"], "hints": {"nudge": "A flag and a multi-bit field need different masks.", "approach": "Annotate the status word with each field’s starting bit and width. Test your extraction reasoning with a word that contains unrelated set bits."}}'),
('freertos-event-bits','{"estimatedMinutes": 30, "focusAreas": ["rtos", "synchronization", "bitwise"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Implement event-bit set, clear, and wait semantics for task synchronization"], "hints": {"nudge": "Which event bits are observed, and when may they be cleared?", "approach": "Separate matching from state mutation. Work through wait-any and wait-all using a mixture of requested and unrelated bits, including the no-match case."}}'),
('debug-saturating-counter','{"estimatedMinutes": 15, "focusAreas": ["debugging", "data-types", "integer-underflow"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "reasoning"}, "targetMinutes": 15, "objectives": ["Fix off-by-one and underflow bugs in an 8-bit counter API"], "hints": {"nudge": "What should happen at each end of the representable range?", "approach": "Trace increment and decrement at zero, one below the maximum, and the maximum. Decide whether to update before performing arithmetic that could wrap."}}'),
('fixed-block-pool','{"estimatedMinutes": 35, "focusAreas": ["memory-management", "constraints", "pointers"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 35, "objectives": ["Allocate and free fixed-size blocks without dynamic memory"], "hints": {"nudge": "How can the allocator tell a valid block start from an interior address?", "approach": "Keep allocation state separate from address calculation. For freeing, reason about pool bounds, block alignment, and whether that block is currently allocated."}}'),
('static-ring-stats','{"estimatedMinutes": 25, "focusAreas": ["static", "state", "integer-widths"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 25, "objectives": ["Maintain rolling sensor statistics with static state and bounded history"], "hints": {"nudge": "What changes when a new sample replaces an old one?", "approach": "Track the retained sample count and which position will be replaced. Distinguish the partially filled buffer from the full buffer, and choose an accumulator width that fits the specified range."}}'),
('bf-memmove','{"estimatedMinutes": 20, "focusAreas": ["pointers", "overlap-safety", "memory-layout"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 20, "objectives": ["Implement overlap-safe memory copy semantics"], "hints": {"nudge": "Which copy direction preserves unread source bytes when the regions overlap?", "approach": "Sketch source and destination intervals for overlap in both directions. Choose a traversal that never overwrites a source byte you still need, and handle zero length before accessing memory."}}'),
('bf-memcpy','{"estimatedMinutes": 15, "focusAreas": ["pointers", "memory-layout", "byte-operations"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 15, "objectives": ["Implement a byte-for-byte non-overlapping memory copy routine"], "hints": {"nudge": "What does copying a byte mean regardless of the pointed-to data type?", "approach": "Reason about source and destination as byte sequences of exactly the requested length. Preserve the original destination return value and check the zero-length contract."}}'),
('isr-byte-ring-lock','{"estimatedMinutes": 35, "focusAreas": ["ring-buffer", "critical-sections", "isr", "volatile"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 35, "objectives": ["Implement an ISR producer ring buffer with locked main-loop reads"], "hints": {"nudge": "Which shared state could change between two main-loop operations?", "approach": "Identify the read-side operation that must be atomic with respect to the ISR. Keep its lock/unlock balanced on every exit path, and trace empty and full transitions separately."}}'),
('parse-ipv4-header','{"estimatedMinutes": 30, "focusAreas": ["packet-parsing", "bit-fields", "endianness"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Parse raw IPv4 header bytes into structured fields with strict validation"], "hints": {"nudge": "The header length field is measured in a different unit from the buffer length.", "approach": "Validate version, header length, and packet bounds before reading optional header bytes. Decode network-order fields explicitly rather than relying on host layout."}}'),
('bit-error-window','{"estimatedMinutes": 35, "focusAreas": ["xor", "popcount", "sliding-window"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 35, "objectives": ["Find the worst 8-bit error window between expected and observed samples"], "hints": {"nudge": "Which bit operation marks positions where two samples disagree?", "approach": "Separate the disagreement map from the moving-window count. Track how the count changes as the window advances, and apply the specified tie rule when updating the best window."}}'),
('aligned-bump-allocator','{"estimatedMinutes": 30, "focusAreas": ["memory-management", "alignment", "constraints"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 30, "objectives": ["Allocate aligned blocks from a fixed memory pool with no free operation"], "hints": {"nudge": "Alignment padding also consumes space in the pool.", "approach": "Reason about the next aligned position and the complete requested interval before changing allocator state. Check overflow and failure cases without advancing the allocation cursor."}}'),
('atomic-spinlock','{"estimatedMinutes": 25, "focusAreas": ["locks", "atomics", "volatile", "ownership"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 25, "objectives": ["Implement a small spinlock API using an atomic compare-and-swap hook"], "hints": {"nudge": "A successful atomic transition is what grants ownership.", "approach": "Express acquisition as an attempted state change through the provided atomic hook. Distinguish one try from repeated attempts, and keep release behavior consistent with the lock’s documented contract."}}'),
('sign-extend-saturate','{"estimatedMinutes": 20, "focusAreas": ["data-types", "integer-promotion", "bitwise"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 20, "objectives": ["Sign-extend packed ADC values and implement saturating 16-bit addition"], "hints": {"nudge": "The packed value’s sign bit may not be the machine type’s sign bit.", "approach": "Treat reconstruction and arithmetic as separate steps. Use a wider intermediate for the sum, compare it against the destination limits, and only then narrow the result."}}'),
('ring-buffer-int','{"estimatedMinutes": 25, "focusAreas": ["queues", "circular-indexing", "state-machines"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 25, "objectives": ["Implement a fixed-capacity FIFO ring buffer used in firmware pipelines"], "hints": {"nudge": "When the indices coincide, what distinguishes an empty ring from a full one?", "approach": "Choose consistent meanings for read index, write index, and count. Trace wraparound and rejected operations while checking that unsuccessful calls leave the ring state unchanged."}}'),
('uart-framed-parser','{"estimatedMinutes": 40, "focusAreas": ["communication-protocols", "state-machines", "uart"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 40, "objectives": ["Parse a byte stream into UART frames with sync, length, and checksum"], "hints": {"nudge": "A stream can stop partway through a frame or contain noise before synchronization.", "approach": "List the parser states and the byte expected in each state. Define recovery after invalid length or checksum, and check which bytes belong in the checksum."}}'),
('bitmap-slot-allocator','{"estimatedMinutes": 25, "focusAreas": ["bitmasks", "resource-allocation", "embedded-c"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "applied"}, "targetMinutes": 25, "objectives": ["Manage 32 fixed resources with a compact allocation bitmap"], "hints": {"nudge": "Each resource corresponds to one bit; what does a set bit mean?", "approach": "Use the specified allocation order when selecting a free bit. Validate release indices before shifting, and reason separately about an exhausted bitmap and an already-free slot."}}'),
('endian-swap-u32','{"estimatedMinutes": 15, "focusAreas": ["endianness", "integer-widths", "bitwise"], "source": "seed", "practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "targetMinutes": 15, "objectives": ["Read big-endian integers and write a little-endian word without unaligned casts"], "hints": {"nudge": "Byte order describes significance, not the host machine’s memory layout.", "approach": "Assign each source byte its position in the reconstructed unsigned value. For writing, extract bytes explicitly in the requested order and avoid alignment assumptions."}}'),
('stable-log-sum-exp','{"practice": {"role": "ai_ml", "level": "Full-time interview", "focus": "applied"}, "hints": {"nudge": "Which transformation preserves relative exponentials while keeping their magnitudes manageable?", "approach": "Factor out a shared offset before exponentiation, then account for it after taking the logarithm. Check a single value, very large inputs, and values far below the maximum."}, "targetMinutes": 25, "objectives": ["Derive and implement a numerically stable log-sum-exp reduction", "Reason about floating-point overflow and translation invariance"]}'),
('adc-quantization-error','{"practice": {"role": "embedded", "level": "Full-time interview", "focus": "fundamentals"}, "hints": {"nudge": "Express the permitted error and the ADC step in the same physical unit.", "approach": "Relate the stated quantization error model to the number of representable codes. Solve the inequality, then check the adjacent integer bit depths against the original error budget."}, "targetMinutes": 10, "objectives": ["Convert quantization error into physical units", "Solve a logarithmic hardware sizing constraint"]}'),
('pthread-counter-interleaving','{"practice": {"role": "operating_systems", "level": "Full-time interview", "focus": "reasoning"}, "hints": {"nudge": "Data-race freedom and preserving a whole logical update are different properties.", "approach": "Write the synchronized read and write actions as separate events. Enumerate orderings consistent with each thread’s program order, tracking each thread’s local value without assuming the whole increment is atomic."}, "targetMinutes": 15, "objectives": ["Distinguish a data race from a lost update", "Enumerate legal synchronized interleavings"]}'),
('best-f1-threshold','{"practice": {"role": "ai_ml", "level": "Full-time interview", "focus": "applied"}, "hints": {"nudge": "Can a threshold separate examples that have exactly the same score?", "approach": "Track confusion counts as a threshold moves across distinct score groups. Evaluate only realizable predictions and apply the specified tie rule; consider comparing metric ratios without rounding."}, "targetMinutes": 25, "objectives": ["Convert scores into thresholded predictions", "Compute F1 from confusion counts", "Process tied scores as one decision block", "Choose deterministic optima without floating-point tie errors"]}'),
('precision-under-prevalence-shift','{"practice": {"role": "ai_ml", "level": "Full-time interview", "focus": "reasoning"}, "hints": {"nudge": "Precision depends on how common the positive class is in the evaluated population.", "approach": "Build a hypothetical population using the stated prevalence. Apply true-positive and false-positive rates to their own populations, then reason about the composition of predicted positives."}, "targetMinutes": 6, "objectives": ["Apply Bayes’ rule to classifier evaluation", "Distinguish precision from recall", "Reason about the base-rate effect"]}'),
('roc-auc-with-tied-scores','{"practice": {"role": "ai_ml", "level": "Full-time interview", "focus": "reasoning"}, "hints": {"nudge": "What does a positive-negative pair contribute when their scores are tied?", "approach": "Compare the ranking of each positive-negative pair using the tie convention in the statement. Normalize by the number of such pairs rather than by the number of observations."}, "targetMinutes": 6, "objectives": ["Compute ROC-AUC from positive-negative rankings", "Handle tied classifier scores consistently"]}'),
('logistic-gradient-at-origin','{"practice": {"role": "ai_ml", "level": "Full-time interview", "focus": "fundamentals"}, "hints": {"nudge": "Does a balanced label count imply that feature-weighted residuals cancel?", "approach": "Differentiate the mean loss before substituting the current weights. Track the feature-weighted residual contribution of each example, and evaluate the regularization term at the specified point."}, "targetMinutes": 8, "objectives": ["Derive the logistic cross-entropy gradient", "Distinguish mean and summed objectives", "Evaluate the L2 gradient at zero"]}')
) UPDATE problems SET metadata=json_set(metadata,
 '$.practice',json(COALESCE(json_extract(metadata,'$.practice'),json_extract(content,'$.practice'))),
 '$.hints',json(COALESCE(json_extract(metadata,'$.hints'),json_extract(content,'$.hints'))),
 '$.targetMinutes',COALESCE(json_extract(metadata,'$.targetMinutes'),json_extract(content,'$.targetMinutes')),
 '$.objectives',json(COALESCE(json_extract(metadata,'$.objectives'),json_extract(content,'$.objectives'))))
FROM enrichment WHERE problems.slug=enrichment.slug;
-- Handle locally authored content that is not part of the checked-in catalog.
UPDATE problems SET metadata=json_set(metadata,
 '$.practice',json_object('role',CASE WHEN category IN ('ai_ml','computer_vision','computer_architecture','operating_systems') THEN category ELSE 'embedded' END,'level','Full-time interview','focus','applied'),
 '$.targetMinutes',COALESCE(json_extract(metadata,'$.targetMinutes'),json_extract(metadata,'$.estimatedMinutes'),25),
 '$.objectives',json(COALESCE(json_extract(metadata,'$.objectives'),json_array(short_description))))
 WHERE json_type(metadata,'$.practice') IS NULL;
UPDATE problems SET metadata=json_set(metadata,'$.hints',json_object('nudge','Identify the key input, output, and boundary conditions in the public specification.','approach','Work through a small example by hand. Identify an invariant you can preserve and compare your strategy with the stated constraints before implementing it.')) WHERE json_type(metadata,'$.hints') IS NULL;
UPDATE interviews SET contract=json_object(
 'role',COALESCE((SELECT json_extract(p.metadata,'$.practice.role') FROM interview_problems ip JOIN problems p ON p.id=ip.problem_id WHERE ip.interview_slug=interviews.slug ORDER BY ip.position LIMIT 1),'embedded'),
 'preset','custom','level','Full-time interview',
 'targetMinutes',COALESCE((SELECT sum(CAST(json_extract(p.metadata,'$.targetMinutes') AS INTEGER)) FROM interview_problems ip JOIN problems p ON p.id=ip.problem_id WHERE ip.interview_slug=interviews.slug),0),
 'objectives',json_array(description));
